import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice headless mode"""
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(uploaded.filename):
        return jsonify({"error": "File type not allowed"}), 415

    # Get optional output format parameter
    output_format = request.form.get('format', 'pdf')

    # Create job directory
    job_id = generate_job_id(uploaded.filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    # Save uploaded file
    safe_name = secure_filename(uploaded.filename)
    input_path = os.path.join(job_dir, safe_name)
    uploaded.save(input_path)

    # Build conversion command
    # The format parameter is passed directly to libreoffice --convert-to
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {job_dir} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            text=True
        )

        if result.returncode != 0:
            return jsonify({
                "error": "Conversion failed",
                "job_id": job_id,
                "detail": result.stderr[:200]
            }), 500

        # Find output file
        output_ext = output_format.split(':')[0] if ':' in output_format else output_format
        base_name = os.path.splitext(safe_name)[0]
        output_path = os.path.join(job_dir, f"{base_name}.{output_ext}")

        if not os.path.exists(output_path):
            # Try to find any new file in job_dir
            files = [f for f in os.listdir(job_dir) if f != safe_name]
            if files:
                output_path = os.path.join(job_dir, files[0])
            else:
                return jsonify({"error": "Output file not found"}), 500

        return send_file(output_path, as_attachment=True)

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timeout"}), 504
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        # Cleanup is handled by cron job every 5 minutes
        pass

@app.route('/api/v1/formats', methods=['GET'])
def list_formats():
    """List supported output formats"""
    return jsonify({
        "input": list(ALLOWED_EXTENSIONS),
        "output": ["pdf", "html", "txt", "epub", "docx"]
    })

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
